import json

with open('/app/output/solution.json', 'r') as f:
    data = json.load(f)

# Find BST station records
print("=== BST Station Examples ===")
bst_count = 0
for record in data['records'][:200]:
    if record['station'] == 'BST' and bst_count < 2:
        print(json.dumps(record, indent=2, ensure_ascii=False))
        print()
        bst_count += 1

# Show statistics by station
station_stats = {}
for record in data['records']:
    station = record['station']
    if station not in station_stats:
        station_stats[station] = {'total': 0, 'segments': 0, 'unknown': 0}

    station_stats[station]['total'] += 1
    for norm in record['normalized']:
        station_stats[station]['segments'] += 1
        if norm['pred_code'] == 'UNKNOWN':
            station_stats[station]['unknown'] += 1

print("=== Statistics by Station ===")
for station in sorted(station_stats.keys()):
    stats = station_stats[station]
    unknown_pct = stats['unknown'] / stats['segments'] * 100 if stats['segments'] > 0 else 0
    print(f"{station:8s}: {stats['total']:4d} records, {stats['segments']:5d} segments, {stats['unknown']:5d} unknown ({unknown_pct:.1f}%)")
EOF
